import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Week 16 — Final Presentations","description":"","frontmatter":{"source":"weeks/16-final-presentations/README.md"},"headers":[],"relativePath":"weeks/16-final-presentations/index.md","filePath":"weeks/16-final-presentations/index.md"}'),n={name:"weeks/16-final-presentations/index.md"};function i(s,e,d,l,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-16--final-presentations" tabindex="-1">Week 16 — Final Presentations <a class="header-anchor" href="#week-16--final-presentations" aria-label="Permalink to &quot;Week 16 — Final Presentations&quot;">​</a></h1><blockquote><p>Finals week. There is no final examination: your team presents its contribution with a live demo in the scheduled final exam period, and the final project is due at the start of that period.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Seminar and Lab</strong></td><td>None. Team presentations run in the course&#39;s scheduled <strong>final exam period</strong> (Regulation H-1-b): [day, time and room, on Canvas]</td></tr><tr><td><strong>Due at the start of the period</strong></td><td>The team&#39;s work in the class fork (staff tag <code>main</code> as <code>final</code>), the final report, each member&#39;s peer evaluation 3, and the CS [5xxx] study paper</td></tr><tr><td><strong>AI use this week</strong></td><td>🔴 AI off for peer evaluation 3 and the limitations, contributions and reflection sections of the report. 🟡 AI limited for the rest of the final report</td></tr><tr><td><strong>Team project</strong></td><td>The Final: 45 points, the report and repository (35) and the presentation (10) (<a href="./../../project/milestones.html#final">milestones</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>The study paper on Canvas (<a href="./../../graduate/empirical-study.html#the-paper">the paper</a>)</td></tr></tbody></table><h2 id="the-presentation" tabindex="-1">The presentation <a class="header-anchor" href="#the-presentation" aria-label="Permalink to &quot;The presentation&quot;">​</a></h2><p>Ten minutes per team, with a live demo: what you contributed and why, the contribution working on the <code>final</code> tag, one check rerun live and compared with your report, and one honest limitation. The full guide and rubric are in <a href="./../../project/final-presentation.html">The Final Presentation</a>.</p><p>Before the period:</p><ul><li>☐ <strong>Merge everything</strong> you want graded into <code>main</code> before the period starts.</li><li>☐ <strong>Open a Codespace on the tag 30 minutes early,</strong> already built, with your check&#39;s command ready.</li><li>☐ <strong>Bring your demo script</strong> from week 15, with a fallback for every step.</li></ul><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deliverable</th><th>Who</th><th>Where</th><th>Due</th></tr></thead><tbody><tr><td><strong>The repository snapshot:</strong> <code>main</code>, tagged <code>final</code></td><td>Team</td><td>Team fork</td><td>Start of the final exam period</td></tr><tr><td><strong>The final report</strong> (nine sections, about 2,000–3,500 words)</td><td>Team</td><td>Canvas</td><td>Start of the final exam period</td></tr><tr><td><strong>Peer evaluation 3</strong> (🔴 AI off)</td><td>Each member</td><td>Canvas</td><td>Start of the final exam period</td></tr><tr><td><strong>The study paper</strong> (4–6 pages, ACM format)</td><td>CS [5xxx]</td><td>Canvas</td><td>Start of the final exam period</td></tr><tr><td><strong>The presentation</strong></td><td>Team</td><td>The final exam period</td><td>The period</td></tr></tbody></table><p>The report must match the tagged commit: every number reproducible from <code>final</code> with your one documented command (<a href="./../../project/milestones.html#the-final-report">the final report</a>). No grace token applies to the Final (<a href="./../../assessment/#late-work-and-grace-tokens">late work</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Your Codespace won&#39;t start:</strong> use a teammate&#39;s on the same tag, or a local clone in a dev container.</li><li><strong>The network fails mid-demo:</strong> show the CI run on the <code>final</code> tag or your screenshots, and say why; a fallback with a reason still earns credit.</li><li><strong>Canvas is down at the deadline:</strong> keep the file with its timestamp, tell the instructor at once, and submit when Canvas is back.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Keep following any upstream PR you opened: answer review, or close it politely with a note (<a href="./../../project/contribution-rules.html#optional-upstream-prs-tier-3">contribution rules</a>).</li><li>Revoke the keys and tokens you made for the course at each provider, and stop or delete unused Codespaces (<a href="./../../setup/api-keys.html">API keys and tokens</a>).</li></ul>',15)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
